import sympy as S
from fractions import Fraction as F
from .authoring import maker,finish
from .common import section
q=maker('circle-synthesis',['circle power','cyclic angles','tangent constructions'])
sqrt=S.sqrt
p=[
q(1,r'Chords AB and CD intersect at P inside a circle. If PA=3, PB=12, and PC=4, find PD.',9,[(6,'Add lengths instead of multiplying.'),(11,'Equate total chord lengths.'),(16,'Use the full first chord as one power factor.'),(36,'Report the product without dividing by PC.')],[r'The intersecting-chord relation gives PA·PB=PC·PD.',r'Thus 3·12=4·PD.',r'It follows that PD=9; both products are 36.'],['Use the four distances measured from the same intersection point.','The invariant is a product, not a sum.'],'Choose the correct segments in an interior power relation.',lambda:F(3*12,4),'Exact chord-product equation; proof by similar triangles.',2),
q(2,r'A point P is 13 units from the center O of a circle of radius 5. A tangent from P touches the circle at T. Find PT.',12,[(8,'Subtract the radius from the center distance.'),(18,'Add the radius to the center distance.'),(sqrt(194),'Treat the center distance as a leg.'),(5,'Use the radius as the tangent length.')],[r'The radius OT is perpendicular to the tangent PT.',r'The right triangle OPT has hypotenuse 13 and leg 5.',r'Therefore PT=√(169-25)=12.'],['Join the center to the point of tangency.','The tangent-radius angle is right.'],'Create a right triangle from a tangent.',lambda:sqrt(13**2-5**2),'Coordinate tangent equation or Pythagorean check.',2),
q(3,r'Two secants from an external point P meet a circle in A,B and C,D, in those orders. PA=4, AB=14, PC=6. Find CD.',6,[(12,'Report PD instead of CD.'),(F(28,3),'Use the internal chord as the whole secant.'),(8,'Subtract the two internal lengths without using power.'),(18,'Copy the full first secant length.')],[r'The full first secant is PB=4+14=18.',r'Power gives PA·PB=PC·PD, so PD=72/6=12.',r'The internal length is CD=PD-PC=12-6=6.'],['Label outside, inside, and whole lengths separately.','Each power product uses outside times whole.'],'Distinguish internal and total secant lengths.',lambda:S.solve(S.Eq(4*18,6*(6+S.Symbol('x'))),S.Symbol('x'))[0],'Exact equation using total lengths.'),
q(4,r'Two circles of radii 13 and 15 have centers 14 units apart and intersect at A and B. Find AB.',24,[(12,'Report the half-chord.'),(28,'Use the sum of radii.'),(2*sqrt(120),'Assume the chord bisects the center segment.'),(14,'Use the center distance as the chord.')],[r'Let the common chord meet the center line at H, at distance x from the radius-13 center. The half-chord h satisfies x²+h²=169 and (14-x)²+h²=225.',r'Subtracting gives x=5 and then h=12.',r'The full chord is 24. Unequal radii mean H need not be the midpoint of the centers.'],['The common chord is perpendicular to the line of centers.','Subtract the two circle equations to locate that chord.'],'Combine radical-axis subtraction with a chord altitude.',lambda:2*sqrt(13**2-F(14**2+13**2-15**2,28)**2),'Circle-coordinate intersection.'),
q(5,r'A cyclic quadrilateral has consecutive side lengths 3,4,5,6. Find its area.',6*sqrt(10),[(18,'Treat the quadrilateral as a rectangle.'),(12*sqrt(10),'Omit the halves in triangle areas.'),(3*sqrt(10),'Halve the area twice.'),(sqrt(330),'Use an incorrect semiperimeter factor.')],[r'The semiperimeter is 9. For a cyclic quadrilateral, Brahmagupta’s formula gives $K^2=(9-3)(9-4)(9-5)(9-6)$.',r'This is 6·5·4·3=360.',r'The positive area is $6\sqrt{10}$. Cyclicity is essential for this formula.'],['Use the cyclic condition to relate opposite angles.','The area can be expressed from the four sides and their semiperimeter.'],'Use a cyclic constraint to determine a four-sided area.',lambda:21*sqrt(1-S.Rational(3,7)**2),'Independent split along a diagonal: opposite angles yield cos B=-3/7 and K=21 sin B.'),
q(6,r'A point P lies inside a circle of radius 13, at distance 5 from its center. A chord through P meets the circle at A,B. If PA=8, find PB.',18,[(12,'Report the square root of the power magnitude.'),(9,'Use half the first chord distance.'),(13,'Assume P is the center.'),(21,'Add the radius and the known segment.')],[r'For an interior point, PA·PB=R²-OP².',r'The product is 169-25=144.',r'Therefore PB=144/8=18. The signed power OP²-R² is negative, while the product of these two positive chord lengths is its magnitude.'],['Relate chord power to the center distance.','Keep track of the interior sign convention.'],'Connect center-based power to a noncentral chord.',lambda:S.Rational(13**2-5**2,8),'Exact center-power equation.'),
q(7,r'Triangle ABC is right at A, with AB=6, AC=8. Its incircle touches BC at T. Find BT.',4,[(6,'Report CT.'),(5,'Assume the tangency point bisects the hypotenuse.'),(2,'Report the inradius.'),(8,'Copy AC.')],[r'The hypotenuse is 10, so the semiperimeter is 12.',r'Equal tangent lengths from each vertex give BT=s-AC.',r'Thus BT=12-8=4; CT=6 and the remaining tangent segments check the two legs.'],['Assign equal tangent lengths from each vertex.','Solve their three pairwise sums.'],'Recover a contact segment through equal tangents.',lambda:S.solve([S.Eq(S.Symbol('u')+S.Symbol('v'),6),S.Eq(S.Symbol('u')+S.Symbol('w'),8),S.Eq(S.Symbol('v')+S.Symbol('w'),10)],[S.Symbol('u'),S.Symbol('v'),S.Symbol('w')])[S.Symbol('v')],'Independent tangent-length linear system.',2),
q(8,r'A cyclic quadrilateral ABCD has AC=10, AB=6, BC=8, CD=$5\sqrt3$, and DA=5. Find BD.',4+3*sqrt(3),[(8+6*sqrt(3),'Forget to divide by AC.'),(4-3*sqrt(3),'Subtract rather than add opposite-side products.'),(3+4*sqrt(3),'Pair adjacent sides incorrectly.'),(10,'Assume both diagonals are diameters.')],[r'Ptolemy’s theorem gives AC·BD=AB·CD+BC·DA.',r'Substitution gives 10BD=30√3+40.',r'Therefore BD=4+3√3. The sides adjacent to AC form right triangles, so the stated cyclic configuration exists.'],['Cyclicity supplies a relation between both diagonals and opposite-side products.','Pair opposite sides rather than adjacent ones.'],'Use Ptolemy after checking the geometric configuration.',lambda:S.simplify(S.Point(S.Rational(18,5),S.Rational(24,5)).distance(S.Point(S.Rational(5,2),-5*sqrt(3)/2))),'Coordinate realization on the circle with diameter from (0,0) to (10,0).'),
q(9,r'Two circles of radii 4 and 9 are externally tangent. A common external tangent touches them at A and B. Find AB.',12,[(13,'Use the center distance.'),(5,'Use the radius difference.'),(sqrt(153),'Subtract only one radius square.'),(8,'Use twice the smaller radius.')],[r'The center distance is 4+9=13.',r'Parallel radii to the tangent have difference 9-4=5. A perpendicular construction gives a right triangle with legs AB and 5 and hypotenuse 13.',r'Hence AB=12.'],['Join the centers and draw both radii to the common tangent.','The perpendicular offset is a radius difference.'],'Turn a common tangent into a right triangle of center differences.',lambda:sqrt((4+9)**2-(9-4)**2),'Independent algebraic simplification to 2√(4·9).'),
q(10,r'Points A,B,C lie on a circle. The minor arc AB measures 80°, and C lies on the major arc AB. Find angle ACB in degrees.',40,[(80,'Use the central-angle measure.'),(100,'Halve the major arc instead.'),(160,'Double the intercepted arc.'),(20,'Halve the arc twice.')],[r'The inscribed angle intercepts the arc AB not containing C.',r'That is the stated minor arc of 80°.',r'The angle is half the arc measure, or 40°.'],['Determine which arc does not contain the angle’s vertex.','An inscribed angle subtends half its intercepted arc.'],'Select the correct intercepted arc.',lambda:S.Rational(80,2),'Inscribed-angle theorem with the stated arc location.',2),
q(11,r'A triangle has side lengths 13,14,15. Find its circumradius.',F(65,8),[(F(65,4),'Use 2K instead of 4K in the denominator.'),(F(8,3),'Report the inradius.'),(F(15,2),'Assume the longest side is a diameter.'),(F(105,8),'Use the semiperimeter in place of a side.')],[r'Heron’s formula gives area 84 from semiperimeter 21.',r'An altitude triangle is similar to a right triangle formed by a circumcircle diameter, giving h/b=a/(2R). Together with K=ch/2, this yields R=abc/(4K).',r'Thus R=13·14·15/(4·84)=65/8.'],['Find the area from the three sides.','Connect the sine area formula to a circumcircle chord.'],'Combine area with circumcircle geometry.',lambda:S.Circle(S.Point(0,0),S.Point(14,0),S.Point(5,12)).radius,'Independent circumcenter calculation from coordinates.'),
q(12,r'A square is inscribed in a circle. A second circle is inscribed in the square. What fraction of the larger circle’s area lies outside the smaller circle?',F(1,2),[(F(1,4),'Square an already squared ratio.'),(1-1/sqrt(2),'Use a radius ratio as an area ratio.'),(F(3,4),'Assume the smaller radius is half the larger.'),(2,'Invert the area ratio and omit the subtraction.')],[r'If the square side is s, the inner radius is s/2 and the outer radius is s/√2.',r'The smaller-to-larger area ratio is (s²/4)/(s²/2)=1/2.',r'The requested remaining fraction is 1-1/2=1/2.'],['Relate one radius to a side and the other to a diagonal.','Square the radius ratio before subtracting areas.'],'Coordinate nested figures with the correct area scale.',lambda:1-(S.Rational(1,2)/(1/sqrt(2)))**2,'Exact nested-radius comparison.',2),
q(13,r'Two parallel chords of a circle of radius 10 have lengths 16 and 12 and lie on opposite sides of the center. Find their distance apart.',14,[(2,'Subtract the distances as if both chords were on the same side.'),(28,'Add chord lengths instead of center offsets.'),(7,'Halve the correct center-to-center separation.'),(10,'Assume one chord is a diameter.')],[r'The center-to-chord distances are √(100-8²)=6 and √(100-6²)=8.',r'Each perpendicular meets its chord at the midpoint.',r'Because the chords lie on opposite sides, their separation is 6+8=14.'],['Use half of each chord in its radius triangle.','The stated side-of-center condition decides whether to add or subtract.'],'Combine chord geometry with a positional condition.',lambda:sqrt(100-64)+sqrt(100-36),'Coordinate chord lines y=6 and y=-8.'),
q(14,r'A right triangle has hypotenuse 25 and inradius 3. Find its area.',84,[(75,'Multiply the hypotenuse by the radius only.'),(42,'Halve the inradius–semiperimeter area formula.'),(168,'Omit the half in the right-triangle area.'),(150,'Assume both legs equal the hypotenuse.')],[r'For a right triangle, r=(a+b-c)/2, so a+b=25+6=31.',r'The semiperimeter is (31+25)/2=28.',r'The area is rs=3·28=84. The legs 7 and 24 provide an existence check.'],['Use tangent lengths to relate the radius to the sum of the legs.','Then compute the semiperimeter without finding each leg.'],'Recover area from radius and hypotenuse without solving the sides.',lambda:S.Rational(7*24,2),'Independent 7–24–25 realization with inradius three.')]
e=[
q(101,r'A tangent from an external point P has length 12. A secant meets the circle at A,B with PA=8. Find AB.',10,[(18,'Report the whole secant.'),(6,'Use the tangent length instead of its square.'),(4,'Subtract PA from the tangent.'),(16,'Confuse external and internal lengths.')],[r'Join the tangent point to the secant intersections. The tangent-chord angle relation produces two similar triangles and hence PT²=PA·PB.',r'Thus PB=144/8=18. This is the distance from P to the far intersection, not the length inside the circle.',r'The internal chord segment is AB=PB-PA=10.',r'Check the original power: 8(8+10)=144=12². Labeling the three secant lengths prevents an otherwise convincing wrong answer.'],['Use tangent power and the whole secant length.','Subtract the external portion only after finding the whole.'],'Derive and correctly interpret tangent–secant power.',lambda:S.solve(S.Eq(8*(8+S.Symbol('x')),144),S.Symbol('x'))[0],'Exact reconstructed power equation.',2),
q(102,r'A triangle has sides 5,12,13. Find the distance between its incenter and the vertex opposite the side of length 13.',2*sqrt(2),[(2,'Report the inradius only.'),(4,'Add two perpendicular distances.'),(F(13,2),'Use the circumradius.'),(sqrt(13),'Use an unrelated side as a squared distance.')],[r'The side lengths satisfy 5²+12²=13², so the specified vertex is the right-angle vertex.',r'The area is 30 and the semiperimeter is 15, giving inradius two.',r'Place the legs on the coordinate axes. The incenter is (2,2), so the required distance is 2√2.',r'This uses the side data twice: first to recognize the right angle, then to obtain the radius. The circle’s center is not halfway along the hypotenuse; that would be the circumcenter.'],['Recognize the triangle before choosing a circle formula.','An incenter is equally far from the two perpendicular legs.'],'Distinguish incenter and circumcenter through a local construction.',lambda:S.Point(2,2).distance(S.Point(0,0)),'Independent coordinate realization.',2)]
finish('circle-synthesis','Circles: power, cyclic structure & tangents','Geometry','circle-power circles ratio-geometry',34,'452–493',
 [r'A circle problem often becomes short after you identify which invariant is available: an angle subtending a fixed arc, a power product from a fixed point, or equal tangent lengths. These are different tools, and the location of the point determines which lengths and signs belong in the relation.',r'Draw the center only when its radii create useful perpendiculars or distances. Many cyclic-quadrilateral problems are better solved through angles and diagonals without introducing the center at all.'],
 [section('Power is measured from one point',r'For an external point and a secant, the power product uses the distance to the near intersection times the distance to the far intersection. The internal chord length alone is not one of those factors. If the external segment is x and the internal part is y, the product is x(x+y).',r'A tangent is the limiting case with equal intersection distances, giving the square of its length. For an interior intersection of chords, the product of the two positive segment lengths equals R²-OP². The signed power OP²-R² is negative inside; state which convention you are using.',r'The chord-product theorem follows from similar triangles formed by joining opposite chord endpoints. Equal inscribed angles provide the correspondence. This proof explains why all four lengths must be measured from the same intersection point and why changing only one factor to a full chord breaks the relation.'),
 section('Use the center when it creates perpendiculars',r'A radius to a tangent point is perpendicular to the tangent. The perpendicular from a center to a chord bisects the chord. These facts turn tangent and chord lengths into right-triangle calculations, but the hypotenuse must be the radius or center-to-external-point distance in the correct triangle.',r'For intersecting circles, subtracting their coordinate equations cancels the quadratic terms and locates the common chord on a line perpendicular to the centers. Unequal radii generally put that line away from the midpoint of the center segment. Once its location is known, one radius triangle gives the half-chord.',r'For a common external tangent, parallel radii leave an offset equal to the difference of radii. Together with the center distance and the tangent segment, this forms a right triangle. An internal common tangent uses a sum instead; the drawing must establish which configuration occurs.'),
 section('Cyclic and tangent polygons combine local relations',r'An inscribed angle intercepts the arc not containing its vertex. Opposite angles of a cyclic quadrilateral are supplementary. Ptolemy then relates the product of diagonals to the sum of opposite-side products. Check that supplied side and diagonal data describe a possible figure before using an algebraic identity.',r'Brahmagupta’s area formula applies to a cyclic quadrilateral, not an arbitrary quadrilateral with the same four sides. One derivation splits along a diagonal, uses the supplementary opposite angles, and eliminates the shared angle from the two triangle-area relations. The cyclic condition is the constraint that makes the four sides sufficient.',r'For an incircle, tangent segments from each vertex are equal. Their three pairwise sums recover the side lengths and show that a contact segment is the semiperimeter minus the opposite side. Joining the incenter to all vertices gives K=rs. Combining these two relations can recover an area without solving every side individually.')],
 ['Choose correct power factors and sign conventions.','Use center and tangent constructions only when they add useful relations.','Combine cyclic, area, and equal-tangent identities with feasibility checks.'],
 [r'Use inscribed angles to prove the similar triangles behind chord power.',r'Draw a tangent radius to derive PT²=OP²-R².',r'Partition a triangle into three inradius-height triangles to derive K=rs.'],
 'For a secant, outside times whole is the power product. Outside times inside generally gives the wrong equation even when every length is positive.',e,p,
 dict(prompt=r'An external secant has outside length 5 and inside length 15. Another secant from the same point has outside length 4. Find its inside length.',answer=r'The second inside length is 21.',steps=[r'The first power is 5(5+15)=100.',r'The second whole length is 100/4=25, so its inside length is 25-4=21.']),
 ['tangent–secant power','radical-axis construction','Ptolemy’s theorem','incircle area synthesis'],
 [(r'PA\cdot PB=PC\cdot PD=PT^2','External point power','connecting two secants or a secant and a tangent','A,B and C,D are near/far intersections from the same external point P; T is a tangency point.'),(r'PA\cdot PB=R^2-OP^2','Interior chord power','connecting a chord through an interior point to its center distance','P lies inside the circle between A and B; lengths are positive.'),(r'AC\cdot BD=AB\cdot CD+BC\cdot DA','Ptolemy’s identity','recovering a diagonal in a cyclic quadrilateral','A,B,C,D occur in that order on one circle.'),(r'K=rs=\frac{abc}{4R}','Triangle circle-area identities','connecting triangle area with its inradius or circumradius','r is the inradius, R the circumradius, s the semiperimeter, and a,b,c the side lengths.')], 'circle-power')
